import { VideoQuality, VideoSources } from "../types/player";

// YouTube Video Extractor - Extract direct video URLs
export async function extractYouTubeVideo(url: string): Promise<VideoSources> {
  const videoId = extractYouTubeId(url);
  if (!videoId) throw new Error('Invalid YouTube URL');

  try {
    // Use server-side API to extract direct URLs
    const response = await fetch(`/api/youtube-extract?id=${videoId}`);
    
    if (!response.ok) {
      throw new Error(`YouTube extraction failed: ${response.status}`);
    }

    const data = await response.json();
    
    // Return direct video URLs in different qualities
    return {
      mp4: data.formats?.filter((format: any) => format.container === 'mp4' && format.hasVideo && format.hasAudio)
        .map((format: any) => ({
          url: format.url,
          quality: format.qualityLabel || `${format.height}p`,
          width: format.width,
          height: format.height,
          bitrate: format.bitrate
        })) || []
    };
  } catch (error) {
    console.error('YouTube extraction failed:', error);
    throw error;
  }
}

// Vimeo Video Extractor - Extract direct video URLs
export async function extractVimeoVideo(url: string): Promise<VideoSources> {
  const videoId = extractVimeoId(url);
  if (!videoId) throw new Error('Invalid Vimeo URL');

  try {
    // Use server-side API to extract direct URLs
    const response = await fetch(`/api/vimeo-extract?id=${videoId}`);
    
    if (!response.ok) {
      throw new Error(`Vimeo extraction failed: ${response.status}`);
    }

    const data = await response.json();
    
    // Return direct video URLs
    return {
      mp4: data.files?.progressive?.map((file: any) => ({
        url: file.url,
        quality: file.quality,
        width: file.width,
        height: file.height,
        bitrate: file.bitrate
      })) || []
    };
  } catch (error) {
    console.error('Vimeo extraction failed:', error);
    throw error;
  }
}

